import os
from typing import Any, Dict, List, Optional

import requests


def extract_key_values_from_form(image_path: str) -> Dict[str, Any]:
    """
    Extract key-value pairs from a form-like document using Google Cloud Vision OCR.

    Requires:
      - GOOGLE_CLOUD_VISION_API_KEY environment variable
        or pass an API key via the environment.

    Returns a dictionary with:
      - "text": full OCR text
      - "key_values": list of {"key": ..., "value": ...}
      - "raw": raw response payload
    """
    api_key = os.getenv("GOOGLE_CLOUD_VISION_API_KEY")
    if not api_key:
        raise ValueError("Missing GOOGLE_CLOUD_VISION_API_KEY environment variable")

    with open(image_path, "rb") as f:
        image_bytes = f.read()

    endpoint = f"https://vision.googleapis.com/v1/images:annotate?key={api_key}"

    payload = {
        "requests": [
            {
                "image": {"content": image_bytes.decode("latin1")},
                "features": [
                    {"type": "DOCUMENT_TEXT_DETECTION", "maxResults": 1}
                ],
            }
        ]
    }

    # Google Vision expects base64-encoded content; encode explicitly.
    import base64

    payload["requests"][0]["image"]["content"] = base64.b64encode(image_bytes).decode("utf-8")

    resp = requests.post(endpoint, json=payload, timeout=60)
    resp.raise_for_status()
    data = resp.json()

    annotations = data.get("responses", [{}])[0]
    full_text = annotations.get("fullTextAnnotation", {}).get("text", "")

    key_values = _extract_key_value_pairs_from_text(full_text)

    return {
        "text": full_text,
        "key_values": key_values,
        "raw": data,
    }


def _extract_key_value_pairs_from_text(text: str) -> List[Dict[str, str]]:
    """
    Heuristic extraction of key-value pairs from OCR text.
    Designed for form-like documents where lines often look like:
      Name: John Doe
      Date - 2024-01-01
    """
    pairs: List[Dict[str, str]] = []
    seen = set()

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        key = value = None

        for sep in (":", " - ", " — ", "="):
            if sep in line:
                parts = line.split(sep, 1)
                left = parts[0].strip()
                right = parts[1].strip()
                if left and right:
                    key, value = left, right
                    break

        if key and value:
            normalized = (key.lower(), value)
            if normalized not in seen:
                seen.add(normalized)
                pairs.append({"key": key, "value": value})

    return pairs


def extract_layout_text_blocks(image_path: str) -> Dict[str, Any]:
    """
    Optional helper to expose OCR layout blocks/paragraphs when available.
    """
    api_key = os.getenv("GOOGLE_CLOUD_VISION_API_KEY")
    if not api_key:
        raise ValueError("Missing GOOGLE_CLOUD_VISION_API_KEY environment variable")

    with open(image_path, "rb") as f:
        image_bytes = f.read()

    endpoint = f"https://vision.googleapis.com/v1/images:annotate?key={api_key}"

    import base64

    payload = {
        "requests": [
            {
                "image": {"content": base64.b64encode(image_bytes).decode("utf-8")},
                "features": [
                    {"type": "DOCUMENT_TEXT_DETECTION", "maxResults": 1}
                ],
            }
        ]
    }

    resp = requests.post(endpoint, json=payload, timeout=60)
    resp.raise_for_status()
    data = resp.json()
    annotation = data.get("responses", [{}])[0].get("fullTextAnnotation", {})

    blocks = []
    for page in annotation.get("pages", []):
        for block in page.get("blocks", []):
            block_text = []
            for para in block.get("paragraphs", []):
                for word in para.get("words", []):
                    symbols = word.get("symbols", [])
                    word_text = "".join(s.get("text", "") for s in symbols)
                    block_text.append(word_text)
                block_text.append("\n")
            blocks.append(" ".join(block_text).strip())

    return {
        "text": annotation.get("text", ""),
        "blocks": blocks,
        "raw": data,
    }
